import { useEffect, useState } from 'react';
import { createTask, deleteTask, getAssignableUsers, getTasks, updateTask } from './api';
import './task.css';

function getToday() {
    const today = new Date();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const day = String(today.getDate()).padStart(2, '0');
    return `${today.getFullYear()}-${month}-${day}`;
}

function Task({ search = '', compact = false, onStats, assignedBy = 'Current user', assignedTo = 'Current user', assignedUserId, userRole = 'User' }) {
    const [tasks, setTasks] = useState([]);
    const [newTask, setNewTask] = useState({ title: '', description: '', priority: 'medium', status: 'pending', dueDate: '' });
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState('');
    const [assignableUsers, setAssignableUsers] = useState([]);
    const [selectedAssignee, setSelectedAssignee] = useState(assignedUserId || '');
    const [selectedFilter, setSelectedFilter] = useState('all');

    useEffect(() => {
        async function loadTasks() {
            try {
                const response = await getTasks();
                setTasks(response.data.map((task) => ({ ...task, id: task._id, done: task.completed })));
            } catch (loadError) {
                setError(loadError.message);
            } finally {
                setIsLoading(false);
            }
        }
        loadTasks();
    }, []);

    useEffect(() => {
        if (userRole === 'User') return;
        getAssignableUsers()
            .then((response) => {
                setAssignableUsers(response.data);
                if (!selectedAssignee && response.data.length > 0) setSelectedAssignee(response.data[0]._id);
            })
            .catch((loadError) => setError(loadError.message));
    }, [userRole]);

    useEffect(() => {
        const completed = tasks.filter((task) => task.done).length;
        onStats?.({ total: tasks.length, completed, remaining: tasks.length - completed });
    }, [tasks, onStats]);

    async function handleSubmit(event) {
        event.preventDefault();
        if (!newTask.title.trim()) return;
        if (newTask.dueDate && newTask.dueDate < getToday()) {
            setError('Due date cannot be before today');
            return;
        }
        setError('');
        try {
            const response = await createTask({ ...newTask, title: newTask.title.trim(), dueDate: newTask.dueDate || null, assignedUser: userRole === 'User' ? undefined : selectedAssignee });
            const task = response.data;
            setTasks((currentTasks) => [{ ...task, id: task._id, done: task.completed }, ...currentTasks]);
            setNewTask({ title: '', description: '', priority: 'medium', status: 'pending', dueDate: '' });
        } catch (submitError) {
            setError(submitError.message);
        }
    }

    async function toggleTask(task) {
        setError('');
        try {
            const response = await updateTask(task.id, { completed: !task.done });
            setTasks((currentTasks) => currentTasks.map((item) => (
                item.id === task.id ? { ...item, done: response.data.completed } : item
            )));
        } catch (updateError) {
            setError(updateError.message);
        }
    }

    async function removeTask(taskId) {
        setError('');
        try {
            await deleteTask(taskId);
            setTasks((currentTasks) => currentTasks.filter((task) => task.id !== taskId));
        } catch (deleteError) {
            setError(deleteError.message);
        }
    }

    const filters = [
        { key: 'all', label: 'All tasks', matches: () => true },
        { key: 'completed', label: 'Completed', matches: (task) => task.done },
        { key: 'active', label: 'Active', matches: (task) => !task.done && task.status === 'in-progress' },
        { key: 'inactive', label: 'Inactive', matches: (task) => !task.done && task.status === 'pending' },
        { key: 'opened', label: 'Opened', matches: (task) => !task.done },
        { key: 'closed', label: 'Closed', matches: (task) => task.done },
    ];
    const searchTasks = tasks.filter((task) => task.title.toLowerCase().includes(search.toLowerCase()));
    const activeFilter = filters.find((filter) => filter.key === selectedFilter) || filters[0];
    const filteredTasks = searchTasks.filter(activeFilter.matches);
    const activeTasks = filteredTasks.filter((task) => !task.done);
    const completedTasks = filteredTasks.filter((task) => task.done);

    function renderTask(task) {
        const assigned = task.assignedUser?.fullname || assignedTo;
        return (
            <div className={`quick-task ${task.done ? 'done' : ''} ${task.assignedUser ? 'assigned-task' : ''}`} key={task.id}>
                <input type="checkbox" checked={task.done} onChange={() => toggleTask(task)} aria-label={`Complete ${task.title}`} />
                <span className="task-content"><strong>{task.title}</strong>{task.description && <small>{task.description}</small>}<em>{task.priority} priority · {task.status || (task.done ? 'completed' : 'pending')}{task.dueDate ? ` · due ${new Date(task.dueDate).toLocaleDateString()}` : ''}</em><small>Assigned by {task.creator?.fullname || assignedBy} · Assigned to {assigned}</small></span>
                <button className="delete-task" type="button" onClick={() => removeTask(task.id)} aria-label={`Delete ${task.title}`}>x</button>
            </div>
        );
    }

    return (
        <article className={`panel task-panel ${compact ? 'task-panel-compact' : 'task-page-panel'}`}>
            <div className="panel-heading">
                <div><h2>{compact ? 'My Tasks' : 'Tasks'}</h2><p>{compact ? 'Complete your tasks for today.' : 'Create and manage your tasks.'}</p></div>
                <span>{tasks.filter((task) => task.done).length}/{tasks.length}</span>
            </div>
            <div className="task-filter-bar">
                <label className="task-filter-select">View tasks
                    <select value={selectedFilter} onChange={(event) => setSelectedFilter(event.target.value)} aria-label="View tasks">
                        {filters.map((filter) => <option value={filter.key} key={filter.key}>{filter.label} ({searchTasks.filter(filter.matches).length})</option>)}
                    </select>
                </label>
            </div>
            {userRole !== 'User' && <form className="quick-task-form" onSubmit={handleSubmit}>
                <input value={newTask.title} onChange={(event) => setNewTask({ ...newTask, title: event.target.value })} placeholder="Task title" aria-label="Task title" required />
                <textarea value={newTask.description} onChange={(event) => setNewTask({ ...newTask, description: event.target.value })} placeholder="Description" aria-label="Task description" rows="2" />
                <div className="task-form-options">
                    <label>Priority
                        <select value={newTask.priority} onChange={(event) => setNewTask({ ...newTask, priority: event.target.value })}>
                            <option value="low">Low</option>
                            <option value="medium">Medium</option>
                            <option value="high">High</option>
                        </select>
                    </label>
                    <label>Status
                        <select value={newTask.status} onChange={(event) => setNewTask({ ...newTask, status: event.target.value })}>
                            <option value="pending">Pending</option>
                            <option value="in-progress">In progress</option>
                            <option value="completed">Completed</option>
                        </select>
                    </label>
                    <label>Due date
                        <input type="date" min={getToday()} value={newTask.dueDate} onChange={(event) => setNewTask({ ...newTask, dueDate: event.target.value })} />
                    </label>
                    <label>Assigned by<input value={assignedBy} readOnly aria-label="Assigned by" /></label>
                    <label>Assign to<select value={selectedAssignee} onChange={(event) => setSelectedAssignee(event.target.value)} aria-label="Assign to" required><option value="" disabled>Select a user</option>{assignableUsers.map((assignableUser) => <option value={assignableUser._id} key={assignableUser._id}>{assignableUser.fullname} ({assignableUser.role})</option>)}</select></label>
                </div>
                <button type="submit">Add</button>
            </form>}
            {userRole === 'User' && <p className="task-permission-note">Only Managers and Admins can create and assign tasks.</p>}
            {error && <p className="task-error" role="alert">{error}</p>}
            {isLoading ? <p className="task-empty">Loading tasks...</p> : (
                <div className="task-list">
                    {activeTasks.length === 0 && completedTasks.length === 0 && <p className="task-empty">No tasks found.</p>}
                    {activeTasks.length > 0 && <section className="task-group" aria-labelledby="active-tasks-title"><h3 id="active-tasks-title">Active tasks <span>{activeTasks.length}</span></h3>{activeTasks.map(renderTask)}</section>}
                    {completedTasks.length > 0 && <section className="task-group completed-group" aria-labelledby="completed-tasks-title"><h3 id="completed-tasks-title">Completed tasks <span>{completedTasks.length}</span></h3>{completedTasks.map(renderTask)}</section>}
                </div>
            )}
        </article>
    );
}

export default Task;
